+import { expect, test } from "bun:test";
+import { creditOrders, pointsFor } from "./loyalty.ts";
+import type { Store } from "./store.ts";
+
+function memoryStore(): Store & { values: Map<string, number> } {
+  const values = new Map<string, number>();
+  return {
+    values,
+    get: async (key) => values.get(key),
+    set: async (key, value) => {
+      values.set(key, value);
+    },
+  };
+}
+
+test("an order earns one point per whole euro", () => {
+  expect(pointsFor({ id: "o1", customerId: "ana", totalCents: 1299 })).toBe(12);
+});
+
+test("each order credits its customer's balance", async () => {
+  const store = memoryStore();
+  store.values.set("points:ana", 3);
+  await creditOrders(store, [
+    { id: "o1", customerId: "ana", totalCents: 1250 },
+    { id: "o2", customerId: "bo", totalCents: 499 },
+  ]);
+  expect(store.values).toEqual(
+    new Map([
+      ["points:ana", 15],
+      ["points:bo", 4],
+    ]),
+  );
+});
