@@ -0,0 +1,18 @@
+import type { Order } from "./orders.ts";
+import type { Store } from "./store.ts";
+
+/** One point per whole euro the order took. */
+export function pointsFor(order: Order): number {
+  return Math.floor(order.totalCents / 100);
+}
+
+async function addPoints(store: Store, customerId: string, points: number): Promise<void> {
+  const key = `points:${customerId}`;
+  const balance = (await store.get(key)) ?? 0;
+  await store.set(key, balance + points);
+}
+
+/** Credits each order's points to its customer's balance. */
+export async function creditOrders(store: Store, orders: Order[]): Promise<void> {
+  await Promise.all(orders.map((order) => addPoints(store, order.customerId, pointsFor(order))));
+}
